package observe

import (
	"context"
	"io"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
	"github.com/emergingrobotics/erg/internal/config"
)

func TestReaderSourceEmitsLines(t *testing.T) {
	src, err := BuildSource(config.SourceConfig{Kind: "stdin"}, strings.NewReader("a\nb\nc\n"))
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	ch, err := src.Events(context.Background())
	if err != nil {
		t.Fatalf("events: %v", err)
	}
	var got []string
	for ev := range ch {
		got = append(got, ev.Text)
	}
	if strings.Join(got, ",") != "a,b,c" {
		t.Fatalf("got %v", got)
	}
}

func TestMatchTrigger(t *testing.T) {
	tr, err := BuildTrigger(config.TriggerConfig{Kind: "match", Pattern: `(?i)error`})
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	if !tr.Match(Event{Text: "an ERROR happened"}) {
		t.Fatal("should match")
	}
	if tr.Match(Event{Text: "all good"}) {
		t.Fatal("should not match")
	}
}

func TestDriverReactsOnlyToMatches(t *testing.T) {
	src, _ := BuildSource(config.SourceConfig{Kind: "stdin"},
		strings.NewReader("ok\nERROR: disk full\nok again\nERROR: oom\n"))
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "match", Pattern: "ERROR"})

	var mu sync.Mutex
	var prompts []string
	var statuses []agent.AgentStatus

	d := &Driver{
		Source:  src,
		Trigger: tr,
		Prompt:  "Event: {{.Event}}",
		React: func(_ context.Context, prompt string) (agent.AgentStatus, error) {
			mu.Lock()
			prompts = append(prompts, prompt)
			mu.Unlock()
			return agent.StatusIdle, nil
		},
		Status: func(s agent.AgentStatus) {
			mu.Lock()
			statuses = append(statuses, s)
			mu.Unlock()
		},
	}
	if err := d.Run(context.Background()); err != nil {
		t.Fatalf("run: %v", err)
	}

	if len(prompts) != 2 {
		t.Fatalf("expected 2 reactions, got %d: %v", len(prompts), prompts)
	}
	if prompts[0] != "Event: ERROR: disk full" {
		t.Fatalf("prompt render wrong: %q", prompts[0])
	}
	// First status is idle (watching), last is done (stream ended).
	if statuses[0] != agent.StatusIdle || statuses[len(statuses)-1] != agent.StatusDone {
		t.Fatalf("status lifecycle wrong: %v", statuses)
	}
	// A reaction flips to working then back to idle.
	if !containsStatus(statuses, agent.StatusWorking) {
		t.Fatal("expected a working status during a reaction")
	}
}

func TestDriverReportsBlockedReaction(t *testing.T) {
	src, _ := BuildSource(config.SourceConfig{Kind: "stdin"}, strings.NewReader("go\n"))
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "every"})
	var mu sync.Mutex
	var statuses []agent.AgentStatus
	d := &Driver{
		Source:  src,
		Trigger: tr,
		React:   func(context.Context, string) (agent.AgentStatus, error) { return agent.StatusBlocked, nil },
		Status:  func(s agent.AgentStatus) { mu.Lock(); statuses = append(statuses, s); mu.Unlock() },
	}
	if err := d.Run(context.Background()); err != nil {
		t.Fatalf("run: %v", err)
	}
	if !containsStatus(statuses, agent.StatusBlocked) {
		t.Fatalf("a blocked reaction should report blocked, got %v", statuses)
	}
}

func TestDriverCancellation(t *testing.T) {
	// A blocking source (never sends) so Run only ends on cancellation.
	pr, pw := io.Pipe()
	defer pw.Close()
	src := &readerSource{r: pr}
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "every"})

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() {
		done <- (&Driver{Source: src, Trigger: tr, React: func(context.Context, string) (agent.AgentStatus, error) { return agent.StatusIdle, nil }}).Run(ctx)
	}()
	cancel()
	select {
	case err := <-done:
		if err == nil {
			t.Fatal("expected cancellation error")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after cancel")
	}
}

func containsStatus(ss []agent.AgentStatus, want agent.AgentStatus) bool {
	for _, s := range ss {
		if s == want {
			return true
		}
	}
	return false
}

package skill

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeSkill(t *testing.T, dir, content string) string {
	t.Helper()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "SKILL.md")
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return dir
}

func TestLoadParsesFrontmatter(t *testing.T) {
	dir := writeSkill(t, filepath.Join(t.TempDir(), "deploy"),
		"---\nname: deploy\ndescription: how to deploy the service\n---\nRun make deploy, then verify.\n")
	s, err := Load(dir)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if s.Name != "deploy" || s.Description != "how to deploy the service" {
		t.Fatalf("frontmatter wrong: %+v", s)
	}
	if s.Body != "Run make deploy, then verify." {
		t.Fatalf("body wrong: %q", s.Body)
	}
}

func TestLoadFileDirectly(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "SKILL.md")
	os.WriteFile(path, []byte("---\nname: x\n---\nbody"), 0o644)
	s, err := Load(path)
	if err != nil {
		t.Fatalf("load file: %v", err)
	}
	if s.Name != "x" || s.Body != "body" {
		t.Fatalf("got %+v", s)
	}
}

func TestLoadNoFrontmatter(t *testing.T) {
	dir := writeSkill(t, filepath.Join(t.TempDir(), "notes"), "just some instructions")
	s, err := Load(dir)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if s.Name != "notes" {
		t.Fatalf("expected dir-derived name, got %q", s.Name)
	}
	if s.Body != "just some instructions" {
		t.Fatalf("body wrong: %q", s.Body)
	}
}

func TestLoadMissingIsError(t *testing.T) {
	if _, err := Load(filepath.Join(t.TempDir(), "nope")); err == nil {
		t.Fatal("expected error for missing skill")
	}
}

func TestSection(t *testing.T) {
	skills := []Skill{
		{Name: "deploy", Description: "deploy it", Body: "step 1\nstep 2"},
		{Name: "test", Body: "run make test"},
	}
	got := Section(skills)
	for _, want := range []string{"# Skills", "## Skill: deploy", "deploy it", "step 1", "## Skill: test", "run make test"} {
		if !strings.Contains(got, want) {
			t.Fatalf("section missing %q in:\n%s", want, got)
		}
	}
	if Section(nil) != "" {
		t.Fatal("empty skills should render nothing")
	}
}

// Package skill loads SKILL.md files and renders them into a system-prompt
// section. A skill is a directory containing a SKILL.md (the hax/Claude
// convention) or a path to the file itself. Skills are an extension substrate:
// a shape lists the skills it wants, and their instructions are composed into
// the model's system prompt.
package skill

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Skill is one loaded SKILL.md.
type Skill struct {
	Name        string
	Description string
	Path        string
	Body        string // markdown after the frontmatter
}

// Load resolves path (a directory containing SKILL.md, or a SKILL.md file) and
// parses it. A missing skill is an error: a shape that lists a skill expects it
// to exist.
func Load(path string) (Skill, error) {
	file := path
	if info, err := os.Stat(path); err == nil && info.IsDir() {
		file = filepath.Join(path, "SKILL.md")
	}
	data, err := os.ReadFile(file)
	if err != nil {
		return Skill{}, fmt.Errorf("load skill %q: %w", path, err)
	}
	name, desc, body := parse(string(data))
	if name == "" {
		name = strings.TrimSuffix(filepath.Base(filepath.Dir(file)), string(filepath.Separator))
		if name == "" || name == "." {
			name = filepath.Base(file)
		}
	}
	return Skill{Name: name, Description: desc, Path: file, Body: body}, nil
}

// LoadAll loads every path, preserving order.
func LoadAll(paths []string) ([]Skill, error) {
	skills := make([]Skill, 0, len(paths))
	for _, p := range paths {
		s, err := Load(p)
		if err != nil {
			return nil, err
		}
		skills = append(skills, s)
	}
	return skills, nil
}

// Section renders the loaded skills as a system-prompt block. The full
// instructions are inlined so the model can follow them without a separate
// read; each skill is clearly delimited.
func Section(skills []Skill) string {
	if len(skills) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("# Skills\n\n")
	b.WriteString("You have the following skills. When one applies to the task, follow its instructions exactly.\n")
	for _, s := range skills {
		b.WriteString("\n---\n\n")
		fmt.Fprintf(&b, "## Skill: %s\n", s.Name)
		if s.Description != "" {
			fmt.Fprintf(&b, "%s\n", s.Description)
		}
		if s.Body != "" {
			b.WriteString("\n" + s.Body + "\n")
		}
	}
	return strings.TrimRight(b.String(), "\n")
}

// parse splits YAML-ish frontmatter (name, description) from the body. A file
// without frontmatter returns empty name/description and the whole content as
// the body.
func parse(content string) (name, description, body string) {
	rest := content
	if strings.HasPrefix(content, "---") {
		if end := frontmatterEnd(content); end >= 0 {
			front := content[3:end]
			rest = content[end:]
			rest = strings.TrimPrefix(rest, "---")
			for _, line := range strings.Split(front, "\n") {
				line = strings.TrimSpace(line)
				if v, ok := field(line, "name"); ok {
					name = v
				}
				if v, ok := field(line, "description"); ok {
					description = v
				}
			}
		}
	}
	return name, description, strings.TrimSpace(rest)
}

// frontmatterEnd returns the index of the closing "---" line, or -1.
func frontmatterEnd(content string) int {
	// Skip the opening "---" line.
	nl := strings.IndexByte(content, '\n')
	if nl < 0 {
		return -1
	}
	idx := strings.Index(content[nl:], "\n---")
	if idx < 0 {
		return -1
	}
	return nl + idx + 1 // position of the closing "---"
}

func field(line, key string) (string, bool) {
	prefix := key + ":"
	if !strings.HasPrefix(line, prefix) {
		return "", false
	}
	return strings.TrimSpace(strings.TrimPrefix(line, prefix)), true
}
